mapper.select:
select pkc.*, p.name as product_name, p.product_no, pk.title as knowledge_title, pk.source_type
from product_knowledge_chunk pkc
left join product p on pkc.product_id = p.id
left join product_knowledge pk on pkc.knowledge_id = pk.id

     and pkc.id = #{id}
     and pkc.knowledge_id = #{knowledgeId}
     and pkc.product_id = #{productId}
     and pkc.knowledge_type = #{knowledgeType}
     and pkc.chunk_status = #{chunkStatus}
     and pkc.chunk_title like concat('%', #{chunkTitle}, '%')
     and pkc.chunk_content like concat('%', #{chunkContent}, '%')
     and p.name like concat('%', #{productName}, '%')
     and pk.title like concat('%', #{knowledgeTitle}, '%')

order by pkc.product_id asc, pkc.knowledge_id asc, pkc.chunk_no asc

